from fractions import Fraction

def rref(M, cols):
    R = [[Fraction(x) for x in row] for row in M]
    pivots = []
    for c in range(cols):
        r = len(pivots)
        p = r
        while p < len(R) and R[p][c] == 0:
            p = p + 1
        if p == len(R):
            continue
        R[r], R[p] = R[p], R[r]
        k = R[r][c]
        R[r] = [x / k for x in R[r]]
        for i in range(len(R)):
            k = R[i][c]
            if i != r and k != 0:
                R[i] = [R[i][j] - k * R[r][j] for j in range(len(R[i]))]
        pivots.append(c)
    return R, pivots

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def columns(vectors):
    return [[v[i] for v in vectors] for i in range(len(vectors[0]))]

def pivot_count(vectors):
    return len(rref(columns(vectors), len(vectors))[1])

def shrink_and_extend(label, vectors):
    m = len(vectors[0])
    R, pivots = rref(columns(vectors), len(vectors))
    basis = [vectors[p] for p in pivots]
    print(f"{label}: {', '.join(vec(v) for v in vectors)}")
    print(f"  pivot columns {[p + 1 for p in pivots]}: a basis of the span is {', '.join(vec(v) for v in basis)}")
    print(f"  dimension of the span: {len(basis)}")
    for i in range(m):
        e = [0] * m
        e[i] = 1
        if pivot_count(basis + [e]) > len(basis):
            basis.append(e)
            print(f"  e{i + 1} = {vec(e)} adds a pivot: keep it")
        else:
            print(f"  e{i + 1} = {vec(e)} adds no pivot: skip it")
    print(f"  a basis of R^{m}: {', '.join(vec(v) for v in basis)}")

shrink_and_extend("Example 9", [[1, 2, 0], [2, 4, 0], [0, 1, 1], [1, 3, 1]])
shrink_and_extend("Example 1", [[1, 0, 0], [1, 1, 0], [1, 1, 1]])
shrink_and_extend("Parallel", [[1, 2], [2, 4], [-3, -6]])
shrink_and_extend("With zero", [[0, 0, 0], [0, 1, 1]])

