from fractions import Fraction

def rref(M, cols):
    R = [[Fraction(x) for x in row] for row in M]
    pivots = []
    for c in range(cols):
        r = len(pivots)
        p = r
        while p < len(R) and R[p][c] == 0:
            p = p + 1
        if p == len(R):
            continue
        R[r], R[p] = R[p], R[r]
        k = R[r][c]
        R[r] = [x / k for x in R[r]]
        for i in range(len(R)):
            k = R[i][c]
            if i != r and k != 0:
                R[i] = [R[i][j] - k * R[r][j] for j in range(len(R[i]))]
        pivots.append(c)
    return R, pivots

def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def special(R, pivots, n):
    result = []
    for f in [j for j in range(n) if j not in pivots]:
        s = [Fraction(0)] * n
        s[f] = Fraction(1)
        for i in range(len(pivots)):
            s[pivots[i]] = -R[i][f]
        result.append(s)
    return result

def read_matrix():
    m, n = [int(w) for w in input().split()]
    return [[Fraction(w) for w in input().split()] for i in range(m)]

def line(name, basis):
    print(f"  {name}: dimension {len(basis)}, basis {', '.join(vec(v) for v in basis) or 'none'}")

def four_subspaces(A):
    m, n = len(A), len(A[0])
    R, pivots = rref(A, n)
    At = [[A[i][j] for i in range(m)] for j in range(n)]
    Rt, pt = rref(At, m)
    line("C(A)", [[row[p] for row in A] for p in pivots])
    line("N(A)", special(R, pivots, n))
    line("C(A^T)", R[:len(pivots)])
    line("N(A^T)", special(Rt, pt, m))

k = int(input())
for t in range(k):
    A = read_matrix()
    print(f"A = {show(A)}")
    four_subspaces(A)
